import { FoldHorizontal, Plus } from 'lucide-react';
import { useEffect, useRef, useState, type ComponentProps, type DragEvent, type ReactNode } from 'react';
import { cn } from '../lib/cn';
import { useControllable } from '../lib/use-controllable';

export interface KanbanColumn {
  id: string;
  title: string;
  /** Stage dot: a chart-N token, e.g. `var(--color-chart-1)`. */
  color?: string;
  /** WIP limit: over it the counter turns into «5 / 4» in warning. */
  limit?: number;
  /** Right side of the header, usually the column sum: «1,9 млн ₽». */
  summary?: ReactNode;
}

/** Cards by column id, in display order. */
export type KanbanItems<T> = Readonly<Record<string, readonly T[]>>;

interface Target {
  column: string;
  index: number;
}

const NONE: readonly string[] = [];

const cardSelector = (id: string) => `[data-kanban-id="${CSS.escape(id)}"]`;
const toggleSelector = (column: string) => `[data-kanban-toggle="${CSS.escape(column)}"]`;

/** Moves one card; `index` counts positions in the target column before the move. */
export function moveKanbanItem<T extends { id: string }>(items: KanbanItems<T>, id: string, to: Target): KanbanItems<T> {
  const from = Object.keys(items).find((column) => items[column]?.some((item) => item.id === id));
  if (from === undefined) return items;
  const source = items[from] ?? [];
  const fromIndex = source.findIndex((item) => item.id === id);
  const moving = source[fromIndex];
  if (moving === undefined) return items;
  const index = from === to.column && fromIndex < to.index ? to.index - 1 : to.index;
  const rest = source.filter((item) => item.id !== id);
  const target = from === to.column ? rest : [...(items[to.column] ?? [])];
  target.splice(Math.min(Math.max(0, index), target.length), 0, moving);
  return { ...items, [from]: rest, [to.column]: target };
}

export interface KanbanProps<T extends { id: string }> extends Omit<ComponentProps<'div'>, 'children'> {
  'aria-label': string;
  columns: readonly KanbanColumn[];
  items: KanbanItems<T>;
  onItemsChange: (items: KanbanItems<T>) => void;
  renderCard: (item: T) => ReactNode;
  /** Card name for screen readers and move announcements. */
  getLabel: (item: T) => string;
  onCardClick?: (item: T) => void;
  /** Shows «Добавить» at the bottom of every column. */
  onAdd?: (columnId: string) => void;
  /** Puts a fold button into every column header. A folded column always opens back, even without it. */
  collapsible?: boolean;
  /** Ids of folded columns (controlled). */
  collapsed?: readonly string[];
  defaultCollapsed?: readonly string[];
  onCollapsedChange?: (collapsed: readonly string[]) => void;
}

/**
 * Stages left to right with cards. Cards move by drag and drop or from the keyboard:
 * Alt+← → to the neighbouring column, Alt+↑ ↓ within one. Every move is announced.
 * A column folds into a 48 strip with its title written vertically; cards still drop onto it.
 */
export function Kanban<T extends { id: string }>({
  columns,
  items,
  onItemsChange,
  renderCard,
  getLabel,
  onCardClick,
  onAdd,
  collapsible = false,
  collapsed: collapsedProp,
  defaultCollapsed = NONE,
  onCollapsedChange,
  className,
  ...props
}: KanbanProps<T>) {
  const [collapsed, setCollapsed] = useControllable(collapsedProp, defaultCollapsed, onCollapsedChange);
  const [dragged, setDragged] = useState<string | null>(null);
  const [target, setTarget] = useState<Target | null>(null);
  const [announcement, setAnnouncement] = useState('');
  const board = useRef<HTMLDivElement>(null);
  // `folded` waits for the fold state to match: a controlled board may ignore the toggle
  const refocus = useRef<{ selector: string; folded?: { column: string; value: boolean } } | null>(null);
  // touch drag: a long press arms it, so a quick swipe still scrolls the board
  const touch = useRef<{ id: string; x: number; y: number; timer: number; active: boolean } | null>(null);

  useEffect(() => {
    const element = board.current;
    if (!element) return;
    // React's touchmove is passive; only a native listener can stop the page from scrolling under the finger
    const hold = (event: TouchEvent) => {
      if (touch.current?.active) event.preventDefault();
    };
    element.addEventListener('touchmove', hold, { passive: false });
    return () => element.removeEventListener('touchmove', hold);
  }, []);

  useEffect(() => {
    const next = refocus.current;
    if (next === null) return;
    refocus.current = null;
    if (next.folded && collapsed.includes(next.folded.column) !== next.folded.value) return;
    board.current?.querySelector<HTMLElement>(next.selector)?.focus();
  });

  const toggle = (column: string) => {
    const folding = !collapsed.includes(column);
    // the pressed button unmounts, so focus moves to its twin: the strip or the header button
    refocus.current = { selector: toggleSelector(column), folded: { column, value: folding } };
    setCollapsed(folding ? [...collapsed, column] : collapsed.filter((id) => id !== column));
  };

  const move = (item: T, to: Target) => {
    const next = moveKanbanItem(items, item.id, to);
    const column = columns.find((entry) => entry.id === to.column);
    const list = next[to.column] ?? [];
    const position = list.findIndex((entry) => entry.id === item.id) + 1;
    setAnnouncement(`«${getLabel(item)}» — в «${column?.title ?? to.column}», позиция ${position} из ${list.length}`);
    // a folded column has no cards to focus, so focus stays on its strip
    refocus.current = { selector: collapsed.includes(to.column) ? toggleSelector(to.column) : cardSelector(item.id) };
    onItemsChange(next);
  };

  const targetAt = (x: number, y: number): Target | null => {
    const element = document.elementFromPoint(x, y);
    const column = element?.closest<HTMLElement>('[data-kanban-column]')?.dataset.kanbanColumn;
    if (column === undefined) return null;
    const card = element?.closest<HTMLElement>('[data-kanban-id]');
    const index = card ? (items[column] ?? []).findIndex((entry) => entry.id === card.dataset.kanbanId) : -1;
    if (!card || index < 0) return { column, index: items[column]?.length ?? 0 };
    const rect = card.getBoundingClientRect();
    return { column, index: y > rect.top + rect.height / 2 ? index + 1 : index };
  };

  const endTouch = () => {
    if (touch.current) window.clearTimeout(touch.current.timer);
    touch.current = null;
    setDragged(null);
    setTarget(null);
  };

  const drop = (column: string) => {
    const item = Object.values(items)
      .flat()
      .find((entry) => entry.id === dragged);
    if (item && target) move(item, target.column === column ? target : { column, index: items[column]?.length ?? 0 });
    setDragged(null);
    setTarget(null);
  };

  return (
    <div
      ref={board}
      data-slot="kanban"
      role="region"
      className={cn('flex items-start gap-3 overflow-x-auto rounded-2xl bg-surface-2 p-3', className)}
      {...props}
    >
      {columns.map((column, columnIndex) => {
        const cards = items[column.id] ?? [];
        const over = column.limit !== undefined && cards.length > column.limit;
        const slotAt = dragged !== null && target?.column === column.id ? target.index : null;
        const slot = <div aria-hidden className="h-14 shrink-0 rounded-md border-2 border-dashed border-accent bg-accent-soft" />;
        const counter = column.limit !== undefined ? `${cards.length} / ${column.limit}` : cards.length;
        const dot = column.color ? <span aria-hidden className="size-2 shrink-0 rounded-full" style={{ background: column.color }} /> : null;
        if (collapsed.includes(column.id)) {
          return (
            <section
              key={column.id}
              role="group"
              aria-label={`${column.title}, ${cards.length}`}
              data-slot="kanban-column"
              data-kanban-column={column.id}
              data-collapsed=""
              data-drop-target={slotAt !== null ? '' : undefined}
              onDragOver={(event) => {
                if (dragged === null) return;
                event.preventDefault();
                setTarget({ column: column.id, index: cards.length });
              }}
              onDrop={(event) => {
                event.preventDefault();
                drop(column.id);
              }}
              className="flex w-12 shrink-0 self-stretch rounded-lg bg-fill-1 transition-colors duration-(--duration-quick) not-data-drop-target:hover:bg-fill-2 data-drop-target:bg-[color-mix(in_oklab,var(--color-accent)_6%,transparent)] data-drop-target:shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-accent)_35%,transparent)]"
            >
              <button
                type="button"
                data-kanban-toggle={column.id}
                aria-expanded={false}
                aria-label={`Развернуть колонку «${column.title}»`}
                onClick={() => toggle(column.id)}
                className="flex flex-1 flex-col items-center gap-3 rounded-lg py-3.5 outline-offset-2"
              >
                {dot}
                <span className={cn('text-label-sm font-medium tabular-nums', over ? 'font-semibold text-warning-soft-fg' : 'text-fg-3')}>{counter}</span>
                <span className="text-label-md font-semibold whitespace-nowrap text-fg-1 [writing-mode:vertical-rl]">
                  {column.title}
                  {column.summary ? <> · {column.summary}</> : null}
                </span>
              </button>
            </section>
          );
        }
        return (
          <section
            key={column.id}
            role="group"
            aria-label={`${column.title}, ${cards.length}`}
            data-slot="kanban-column"
            data-kanban-column={column.id}
            onDragOver={(event) => {
              if (dragged === null) return;
              event.preventDefault();
              if (event.target === event.currentTarget || !(event.target instanceof Element) || !event.target.closest('[data-kanban-id]')) {
                setTarget({ column: column.id, index: cards.length });
              }
            }}
            onDrop={(event) => {
              event.preventDefault();
              drop(column.id);
            }}
            className="flex w-[298px] min-w-[264px] shrink-0 flex-col gap-2"
          >
            <header className="group/header flex h-10 items-center gap-2 px-2">
              {dot}
              <h3 className="truncate text-label-md font-semibold text-fg-1">{column.title}</h3>
              <span
                className={cn(
                  'rounded-full px-1.5 text-caption tabular-nums',
                  over ? 'bg-warning-soft font-semibold text-warning-soft-fg' : 'bg-fill-2 text-fg-2',
                )}
              >
                {counter}
              </span>
              <span className="ml-auto text-body-xs whitespace-nowrap text-fg-2 tabular-nums">{column.summary}</span>
              {collapsible ? (
                // zero-wide until the header is hovered or the button focused, so the sum keeps its place at rest
                <button
                  type="button"
                  data-kanban-toggle={column.id}
                  aria-expanded
                  aria-label={`Свернуть колонку «${column.title}»`}
                  onClick={() => toggle(column.id)}
                  className="-ml-2 grid h-6 w-0 shrink-0 place-items-center overflow-hidden rounded-full text-fg-3 opacity-0 transition-opacity duration-(--duration-quick) group-hover/header:ml-0 group-hover/header:w-6 group-hover/header:opacity-100 hover:bg-fill-1 hover:text-fg-1 focus-visible:ml-0 focus-visible:w-6 focus-visible:opacity-100 pointer-coarse:ml-0 pointer-coarse:w-6 pointer-coarse:opacity-100"
                >
                  <FoldHorizontal aria-hidden className="size-4 stroke-[1.75]" />
                </button>
              ) : null}
            </header>
            {cards.length === 0 && slotAt === null ? (
              <div className="flex flex-col items-center gap-1 rounded-md border border-dashed border-border px-4 py-6 text-center">
                <p className="text-label-sm font-medium text-fg-2">Здесь пока пусто</p>
                <p className="text-caption text-fg-3">Перетащите сделку сюда</p>
              </div>
            ) : null}
            {cards.map((item, index) => (
              <div key={item.id} className="contents">
                {slotAt === index ? slot : null}
                <div
                  role="button"
                  tabIndex={0}
                  draggable
                  data-kanban-id={item.id}
                  aria-roledescription="карточка"
                  aria-label={getLabel(item)}
                  data-dragging={dragged === item.id || undefined}
                  onClick={() => onCardClick?.(item)}
                  onDragStart={(event: DragEvent<HTMLDivElement>) => {
                    event.dataTransfer?.setData('text/plain', item.id);
                    setDragged(item.id);
                  }}
                  onDragEnd={() => {
                    setDragged(null);
                    setTarget(null);
                  }}
                  onDragOver={(event) => {
                    if (dragged === null) return;
                    const rect = event.currentTarget.getBoundingClientRect();
                    setTarget({ column: column.id, index: event.clientY > rect.top + rect.height / 2 ? index + 1 : index });
                  }}
                  onTouchStart={(event) => {
                    const point = event.touches[0];
                    if (!point) return;
                    const timer = window.setTimeout(() => {
                      if (!touch.current) return;
                      touch.current.active = true;
                      setDragged(item.id);
                      navigator.vibrate?.(10);
                    }, 350);
                    touch.current = { id: item.id, x: point.clientX, y: point.clientY, timer, active: false };
                  }}
                  onTouchMove={(event) => {
                    const point = event.touches[0];
                    const current = touch.current;
                    if (!point || !current) return;
                    if (current.active) setTarget(targetAt(point.clientX, point.clientY));
                    else if (Math.hypot(point.clientX - current.x, point.clientY - current.y) > 8) endTouch();
                  }}
                  onTouchEnd={(event) => {
                    const point = event.changedTouches[0];
                    if (touch.current?.active && point) {
                      // no click after a drag
                      event.preventDefault();
                      const to = targetAt(point.clientX, point.clientY) ?? target;
                      if (to) move(item, to);
                    }
                    endTouch();
                  }}
                  onTouchCancel={endTouch}
                  onKeyDown={(event) => {
                    if (event.key === 'Enter' || event.key === ' ') {
                      event.preventDefault();
                      onCardClick?.(item);
                      return;
                    }
                    if (!event.altKey) return;
                    const side = { ArrowLeft: -1, ArrowRight: 1 }[event.key];
                    const step = { ArrowUp: -1, ArrowDown: 2 }[event.key];
                    const neighbour = side !== undefined ? columns[columnIndex + side] : undefined;
                    if (neighbour) {
                      event.preventDefault();
                      move(item, { column: neighbour.id, index: items[neighbour.id]?.length ?? 0 });
                    } else if (step !== undefined && index + step >= 0 && index + step <= cards.length) {
                      event.preventDefault();
                      move(item, { column: column.id, index: index + step });
                    }
                  }}
                  className="rounded-xl outline-offset-2 select-none [-webkit-touch-callout:none] transition-opacity duration-(--duration-quick) data-dragging:opacity-40"
                >
                  {renderCard(item)}
                </div>
              </div>
            ))}
            {slotAt !== null && slotAt >= cards.length ? slot : null}
            {onAdd ? (
              <button
                type="button"
                onClick={() => onAdd(column.id)}
                className="flex h-9 items-center gap-1.5 rounded-md px-2 text-label-sm font-medium text-fg-2 hover:bg-fill-1 hover:text-fg-1"
              >
                <Plus aria-hidden className="size-4 stroke-[1.75]" />
                Добавить
              </button>
            ) : null}
          </section>
        );
      })}
      <p role="status" className="sr-only">
        {announcement}
      </p>
    </div>
  );
}

export type KanbanCardProps = ComponentProps<'article'>;

/** Card surface: surface-1, r12, p12, raised shadow; lifts a little on hover. */
export function KanbanCard({ className, ...props }: KanbanCardProps) {
  return (
    <article
      data-slot="kanban-card"
      className={cn('flex flex-col gap-2 rounded-xl bg-surface-1 p-3 text-fg-1 shadow-raised transition-shadow duration-(--duration-quick) hover:shadow-overlay', className)}
      {...props}
    />
  );
}
